programs.haiku:
"""Question and inquiry words, as a lookup on the newest token.

The component's activation is near zero on most tokens and jumps up on words that open
a question or an investigation: "how" above all ("we'll explore how ...", "see how ...",
"examine how ..."), then capitalised question openers ("What", "Why", "Is", "Does",
"Would"), inquiry verbs ("wonder", "explore", "examine", "investigate") and question
marks. Lowercase auxiliaries ("is", "do") and ordinary words get 0. The program reads only
the newest token, so it is causal, and it keeps no state.

What it leaves out: most of the activation's variance is a dense, context-driven bulk
(about +/-0.5 on ordinary words) that no word list describes. On held-out training rows
a full per-token lookup table explains about 7% of the variance; this short list explains
about 4% there, and 3% on eval rows. Switched off, the component's effect on the model is
tiny, and this program's effect is about the same.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

HOW = {"how", "如何", "как", "怎么", "どう"}
WH = {"what", "why", "whether", "who", "which", "where", "when"}
AUX = {"is", "are", "do", "does", "did", "can", "could", "would", "will", "should", "have"}
INQUIRY = {
    "wonder", "wondering", "explore", "exploring", "examine", "examining",
    "investigate", "investigating", "discuss", "study", "determine", "consider",
    "curious", "intriguing",
}
QUESTION_MARKS = {"?", "？"}


def step(carry, prefix, upstream: Mapping):
    """The activation at the newest token, from that token alone."""
    text = prefix.token_strings[-1].strip()
    word = text.lower()
    if word in HOW:
        value = 3.6
    elif text[:1].isupper() and (word in WH or word in AUX):
        value = 1.1
    elif word in WH:
        value = 0.25
    elif word in INQUIRY:
        value = 0.6
    elif word in QUESTION_MARKS:
        value = 0.9
    else:
        value = 0.0
    return carry, value

"""Declaration-start detector in source code (layer 15, MLP down_proj, component 390).

The component is quiet in prose and fires in source code. It is strongest on the
word that opens a function, method or class declaration (public, static, void,
def, func, fn, main, class), on a Java/C# annotation sign (@Test, @Override), and
on the tab indentation that leads into code. Each is about twice as strong inside
a block of braces { ... } as at the top level. Everything else is near zero, with
small positive values for comment markers and spaces, and small noise.

The program tracks brace depth across the document as its only state.
"""

DECLARATION_WORDS = frozenset(
    {"func", "fn", "def", "function", "public", "private", "protected", "static",
     "void", "main", "Main", "class"}
)
COMMENT_MARKS = frozenset({"//", "/**", "*", "*/"})
READS = ()


def step(carry, prefix, upstream):
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    depth = 0 if new_doc or carry is None else carry
    inside = depth > 0
    s = prefix.token_strings[-1]
    w = s.strip()
    if w in DECLARATION_WORDS:
        v = 4.6 if inside else 2.2
    elif w == "@":
        v = 3.6 if inside else 1.8
    elif s.isspace() and "\n" not in s:
        if "\t" in s:
            v = 0.9 if inside else 1.7
        else:
            v = 0.7 if len(s) > 1 else 0.05
    elif w in COMMENT_MARKS:
        v = 0.6
    else:
        v = 0.2 if inside else 0.0
    depth = max(0, depth + s.count("{") - s.count("}"))
    return depth, float(v)

"""Predicts layers.15.mlp.down_proj component 399 from the words just before each token.

The component sits near zero, with a small positive lean, and dips negative where a
sentence is giving a definition: right after a defining phrase ("X means", "refers to",
"defined as", "is called", "a branch of", "a measure of"), where the model is about to
name what the thing is; and somewhat less right after "is a", "are the", "as a".
It leans slightly positive on digits.

The rules are a sketch, not a full account. Token and phrase identity explain only a
few tenths of a percent of the component's variance; its size mostly depends on the wider
passage, which no short rule captures.
"""

READS = ()

BASELINE = 0.047
DEFINING_VERBS = {"means", "involves", "refers", "called", "defined", "describes"}
DEFINING_OF = {"measure", "branch", "consists", "type", "study", "process"}
COPULAS = {"is", "are", "as"}
ARTICLES = {"a", "an", "the"}
SENTENCE_DEFINERS = {"is", "are", "means", "involves", "refers", "defined", "called"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    doc = prefix.document_ids[t]
    # The three tokens before this one, in the same document, nearest first.
    before = []
    for i in range(t - 1, max(-1, t - 4), -1):
        if prefix.document_ids[i] != doc:
            break
        before.append(_word(prefix.token_strings[i]))
    prev = before[0] if before else ""
    prev2 = before[1] if len(before) > 1 else ""
    value = BASELINE
    if prev in DEFINING_VERBS or (prev in {"as", "to"} and prev2 in {"defined", "refers"}) or (
        prev == "of" and prev2 in DEFINING_OF
    ):
        value -= 0.5  # the definition's own opening: "means", "refers to", "defined as"
    elif prev in ARTICLES and prev2 in COPULAS:
        value -= 0.3  # "is [a]", "are [the]", "as [a]"
    elif any(w in SENTENCE_DEFINERS for w in before):
        value -= 0.07  # somewhere inside a defining sentence
    if _word(prefix.token_strings[t]).isdigit():
        value += 0.04
    return carry, float(value)

"""Layout-token guess for layers.15.mlp.down_proj component 406.

What the component does, as far as surface features show: it is a diffuse,
heavy-tailed direction. Most of the time it sits near zero (std about 0.3).
Its positive spikes lean toward layout tokens: paragraph breaks, newlines,
literal backslash-n escapes, and long runs of spaces. Ordinary prose function
words ("the", "of", "and") and digits sit slightly below zero, and end-of-text
markers sit lower still. Nothing simple predicts the large spikes well, so this
program reproduces only the average shape of the component, not its tails.

The values are rounded class means measured on about 4M tokens of training text.
The program reads only the newest token's text.
"""

READS = ()

END_MARKERS = frozenset(["<|im_end|>", "<|endoftext|>"])

FUNCTION_WORDS = frozenset(
    "the a an of and to in is that for on with as by or it be are was this at from which".split()
)


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    bare = text.strip()
    if "\\n" in text:
        value = 0.35  # a literal backslash-n escape, as in code or escaped text
    elif bare == "" and text.count("\n") >= 2:
        value = 0.2  # a paragraph break: blank line or several newlines
    elif bare == "" and "\n" in text:
        value = 0.05  # a single line break
    elif bare == "" and len(text) >= 24:
        value = 0.2  # a very long run of spaces, as in aligned columns
    elif bare == "" and len(text) >= 16:
        value = 0.05  # a long run of spaces
    elif bare == "":
        value = 0.01  # a single space or tab
    elif text in END_MARKERS:
        value = -0.15  # end-of-text markers
    elif bare.isdigit():
        value = -0.03  # digits
    elif bare.lower() in FUNCTION_WORDS:
        value = -0.04  # prose function words
    else:
        value = -0.02  # everything else sits near the component's mean
    return carry, value

"""Layer 15 MLP down_proj, component 407.

What it does: it goes negative on prepositions, most strongly on a preposition that
opens a parenthetical or framing phrase: "According to ...", "..., in particular",
"..., for example", "In fact ...", "For this reason". It is near zero on most other tokens.
Most of its variance is in a long tail that these few rules only partly capture.

The program reads only the newest few tokens and predicts for the newest one:
  - a preposition has a base value: "by" -1.4, "for" -0.5, "in", "per", "under" about -0.4 to -0.3,
    the others 0
  - a preposition after a comma, colon or connective (and, but, so): a further -0.7
  - a preposition at the start of a sentence: a further -0.4
  - a preposition after "according" (as in "according to"): -5 instead
  - a determiner ("this", "a", "the", ...) right after such an opener: -0.3
"""

READS = ()

PREPOSITIONS = {
    "in", "for", "to", "by", "on", "at", "from", "with", "under", "through", "into",
    "about", "over", "after", "before", "during", "between", "per", "via", "without",
    "of", "as", "like", "within", "since", "until",
}
BASE_VALUE = {"by": -1.4, "for": -0.5, "in": -0.3, "per": -0.4, "under": -0.4}
DETERMINERS = {
    "this", "a", "the", "an", "that", "these", "his", "their", "its", "my", "our",
    "your", "me", "us", "example", "instance", "particular", "part", "order", "fact", "all",
}
PAUSES = {",", ";", ":", "(", '"', "“", "—", "-"}
CONNECTIVES = {"so", "but", "and", "thus", "then", "also", "yet", "however", "because", "while", "if", "now"}
SENTENCE_ENDS = {".", "!", "?", ""}  # "" is a line break or the start of a document


def _word(prefix, back):
    """The lowercased token `back` steps before the newest; '' before its document starts."""
    if back >= len(prefix.token_strings) or prefix.document_ids[-1 - back] != prefix.document_ids[-1]:
        return ""
    return prefix.token_strings[-1 - back].strip().lower()


def _opens_phrase(prefix, back):
    """Whether the token `back` steps before the newest is a preposition starting a phrase."""
    if _word(prefix, back) not in PREPOSITIONS:
        return False
    before = _word(prefix, back + 1)
    return before in SENTENCE_ENDS or before in PAUSES or before in CONNECTIVES


def step(carry, prefix, upstream):
    cur, prev = _word(prefix, 0), _word(prefix, 1)
    value = 0.0
    if cur in PREPOSITIONS:
        value = BASE_VALUE.get(cur, 0.0)
        if prev == "according":
            value = -5.0
        elif prev in SENTENCE_ENDS:
            value -= 0.4
        elif prev in PAUSES or prev in CONNECTIVES:
            value -= 0.7
    elif cur in DETERMINERS and (_opens_phrase(prefix, 1) or _opens_phrase(prefix, 2)):
        value = -0.3
    return carry, value

"""Token-level guess at MLP hidden unit 413 of layer 15 (the component's activation).

The component is one rank-one piece of layers.15.mlp.down_proj whose input direction is
(almost exactly) the MLP hidden unit 413 of layer 15, so its activation is that unit's value
times a fixed output scale. The unit is near zero on most tokens. Its larger values are
mostly negative in code, and they depend on context this program cannot see, so only a
small part of its variance is explained by the current token alone.

This program looks only at the newest token and predicts:
  - equality tests (==, !=, ===): a positive value;
  - common code operators and keywords (&&, =>, print, const, return, .log, join):
    a negative value;
  - indentation at the start of a code line (tabs, or two or more spaces): a small negative value;
  - assignment " =": a small negative value;
  - anything else: 0.
"""
import re

READS = ()

POSITIVE = {"==", "!=", "==="}
NEGATIVE = {"&&", "=>", "print", "println", "const", "return", ".log", "join"}


def step(carry, prefix, upstream):
    x = prefix.token_strings[-1]
    s = x.strip()
    if s in POSITIVE:
        value = 1.5
    elif s in NEGATIVE:
        value = -1.5
    elif re.fullmatch(r"[ \t]+", x) and ("\t" in x or len(x) >= 2):
        value = -0.3
    elif x == " =":
        value = -0.3
    else:
        value = 0.0
    return carry, value

"""Activation of one MLP unit (layer 15, unit 414) in Qwen3-1.7B, as a rule-based predictor.

The unit is a sentence-and-copula detector:
- It is strongly positive on forms of "to be" written with a leading space (" is", " was",
  " were", " be", " been", " being", " are", and their translations), most of all where the
  be-verb opens a passive ("was used", "is found"). Contracted forms ("'re", "'m") are weaker.
- It is positive at the end of an ordinary prose sentence (". ? ! 。", or a closing ")." '."')
  and grows with the length of the sentence it closes. Periods after an abbreviation, initial
  or number ("U.S.", "J.", "1.") are not sentence ends and sit near zero.
- It is mildly positive on adverbs that come before a participle ("not", "also", "often").
- It is mildly negative on function words, modals, pronouns, digits and commas, and slightly
  negative elsewhere.
"""
READS = ()

BE_VERBS = {" is", " was", " were", " be", " are", " been", " being", " am",
            " est", " sont", " sono", " ser", " ist", " sind", " быть", " был", " была", " были"}
CONTRACTED_BE = {"'re", "'m", "’re", "’m"}
SENTENCE_ENDS = {".", "?", "!", "。", "？", "！"}
CLOSED_ENDS = {").", "].", '."', ".”", '”.', "%.", "$.", "'."}
ADVERBS = {" not", " also", " often", " usually", " typically", " originally", " commonly"}
MILD_NEGATIVE = {" the", " a", " an", " of", " to", " in", " and", " or", " it", " this", " that",
                 " which", " they", " he", " she", " you", " there", " can", " could", " should",
                 " must", " may", " might", " will", " would", " has", " have", " had", ",", ":",
                 " ", '"', "'"}
SLOPE = 0.2   # per token of sentence so far
CAP = 15      # the sentence-length term stops growing here


def step(carry, prefix, upstream):
    """carry: the number of tokens since the last sentence end in this document."""
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    new_document = len(prefix.document_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    length = 0 if new_document or carry is None else carry

    if token in BE_VERBS:
        value = 6.0
    elif token in CONTRACTED_BE:
        value = 3.5
    elif token in SENTENCE_ENDS:
        word = previous.strip()
        if word.isalpha() and len(word) >= 2:
            value = 1.5 + SLOPE * min(length, CAP)
        else:
            value = 0.8
    elif token in CLOSED_ENDS:
        value = 3.5
    elif token.strip() in SENTENCE_ENDS:
        value = 1.5
    elif token == "\n":
        value = 0.2
    elif token in ADVERBS:
        value = 1.5
    elif token in MILD_NEGATIVE or token.isdigit():
        value = -0.3
    else:
        value = -0.2

    ended = token in SENTENCE_ENDS or token in CLOSED_ENDS or "\n" in token
    return (0 if ended else length + 1), value

"""Linking words (prepositions and relative pronouns) push this component negative.

The component is near zero for most words. It goes negative on the small words that open a
phrase attaching to a preceding word, most of all when that word names a place, a
position, a time span, a person or a group: "the end of", "the children of", "days after",
"the side of", "under", "around", "who" after "people". Other words sit near zero.
"""
import wordnet

READS = ()

OF_WORDS = {"of", "de", "del", "della", "des", "di", "du"}
SPACE_TIME = {"after", "before", "under", "around", "near", "behind", "between", "inside",
              "outside", "during", "prior", "below", "above", "along", "beyond", "within",
              "across", "through", "following", "since", "until"}
RELATIVE = {"who", "whom", "which", "that", "where", "when", "whose"}
PREPOSITIONS = {"to", "in", "on", "at", "by", "for", "from", "with", "about", "as", "into"}
# WordNet lexicographer classes of concrete places, times, people, groups and body parts
PLACE_TIME_PEOPLE = {"noun.location", "noun.time", "noun.person", "noun.group", "noun.body",
                     "noun.animal", "noun.plant"}
# nouns that name a position or a span of time, the head of "the end of", "two days after"
POSITION_TIME = {"end", "top", "side", "bottom", "center", "centre", "middle", "edge", "front",
                 "back", "head", "base", "rest", "day", "days", "week", "weeks", "month",
                 "months", "year", "years", "hour", "hours", "morning", "night", "time"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    about_place = bool(prev) and prev.isalpha() and bool(set(wordnet.categories(prev)) & PLACE_TIME_PEOPLE)
    if word in OF_WORDS:
        if prev in POSITION_TIME:
            return carry, -4.5
        return carry, -1.75 if about_place else -0.98
    if word in SPACE_TIME:
        if prev in POSITION_TIME:
            return carry, -5.0
        return carry, -2.84 if about_place else -1.92
    if word in RELATIVE:
        return carry, -1.84 if about_place else -0.58
    if word in PREPOSITIONS:
        return carry, -0.37 if about_place else -0.1
    return carry, -0.12

"""Component 422 of layer 15's MLP down_proj, read as a 'before / prior to' cue.

Its activation is mostly small and noisy, but it goes clearly negative at a few kinds of
word in procedural text, where the writer is likely to go on with "before" or "prior to":

- action verbs of checking, cleaning, preparing and testing ("verify", "remove", "clean",
  "test", "prepare", "review", "wash" ...), as in "wash thoroughly before use";
- "to" after a participle of being acted on ("applied to", "added to", "subjected to",
  "exposed to"), as in "has been applied to ..." (= "prior to");
- the words "before" and "prior" themselves.

Other "to" is mildly negative, and everything else is about zero. The values are the mean
activations of those groups on training text, so the program predicts the mean of each cue.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

PROCEDURE_VERBS = {
    "verify", "verified", "check", "checking", "checks", "review", "reviewed", "clean",
    "cleaning", "cleaned", "test", "tested", "testing", "read", "confirm", "confirmed",
    "validate", "validation", "examine", "examination", "inspect", "measure", "measured",
    "assess", "assessment", "prepare", "prepared", "preparation", "wash", "washed", "remove",
    "removed", "removing", "install", "update", "updated", "replace", "ensure", "sure",
    "filter", "filtering", "sort", "sorted", "clear", "delete", "deleted", "treated",
    "performed", "analysis", "discuss", "training",
}
PASSIVE_WORDS = {
    "applied", "added", "subjected", "exposed", "used", "required", "necessary", "needed",
    "performed", "treated", "prior", "given", "sent",
}
BEFORE_WORDS = {"before", "prior", "beforehand"}

PROCEDURE_VALUE = -0.6
PASSIVE_TO_VALUE = -0.7
OTHER_TO_VALUE = -0.17
BEFORE_VALUE = -0.45


def _word(text: str) -> str:
    return text.strip().lower()


def step(carry, prefix, upstream: Mapping):
    word = _word(prefix.token_strings[-1])
    if len(prefix.token_strings) > 1:
        previous = _word(prefix.token_strings[-2])
    else:
        previous = ""
    if word in PROCEDURE_VERBS:
        return carry, PROCEDURE_VALUE
    if word in BEFORE_WORDS:
        return carry, BEFORE_VALUE
    if word == "to":
        return carry, PASSIVE_TO_VALUE if previous in PASSIVE_WORDS else OTHER_TO_VALUE
    return carry, 0.0

"""Component L15 down_proj #423: a clause-closing adverb detector.

What it responds to, read off its activations on training text:
- Strongly positive for a discourse adverb set off by a comma, closing an aside:
  "...higher, however, without..." or "...too, that..." or "...though, ...".
  The same word opening a sentence ("However, ...") barely fires, and "even
  though" does not fire at all.
- Positive for other clause-final discourse adverbs ("respectively", "anyway",
  "etc", "again", "today", "here"); "respectively" and "anyway" are in fact
  strong, but the program gives all of them one moderate value. Adverbs ending
  in -ly lean positive, other adverbs only slightly.
- Negative for focus and exemplifying words after a negation or conjunction,
  as in "not only", "not even", "not just", "and even", "auch".
- Everything else is near zero.

It reads only the current word and the word before it, and resets at each
document boundary. It is a rough sketch: it captures a small share of the
variance, and the rest is spread across many words.
"""

from collections.abc import Mapping
from functools import lru_cache

from wordnet import parts_of_speech

READS: tuple[str, ...] = ()

# Discourse adverbs and markers that can close a clause or an aside.
CLOSING_ADVERBS = {
    "however", "though", "too", "anyway", "respectively", "etc", "indeed",
    "really", "sure", "moreover", "apparently", "still", "therefore", "alone",
    "today", "again", "here", "below", "otherwise", "besides", "actually",
}

# Words that set up a continuation: focus particles and exemplifiers.
FOCUS_WORDS = {
    "auch", "also", "even", "just", "only", "similarly", "finally", "such",
    "including", "especially", "nur",
}

# A focus word after one of these is the second half of "not only / not even".
NEGATION_LEADS = {"not", "and", "or", "but", "nor"}

# The start of a sentence or a document.
SENTENCE_START = {"", ".", "!", "?", "\n", '"'}


@lru_cache(maxsize=None)
def is_adverb(word: str) -> bool:
    """Whether WordNet lists this word as an adverb."""
    return word.isalpha() and "adverb" in parts_of_speech(word)


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1]
    )
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""

    if word in CLOSING_ADVERBS:
        if before == ",":
            value = 6.5  # set off by a comma: an aside that is closing
        elif before in SENTENCE_START:
            value = 1.0  # opening a sentence: hardly fires
        else:
            value = 2.0
    elif word in FOCUS_WORDS:
        value = -1.5 if before in NEGATION_LEADS else 0.0
    elif is_adverb(word):
        value = 1.0 if word.endswith("ly") else 0.2
    else:
        value = 0.0
    return carry, float(value)

"""Package names in import lines that belong to widely used libraries.

Component layers.15.mlp.down_proj:425 is switched on by the package path of an import:
  - the name of a well-known standard or framework package, right after its root, is
    strongly positive: `import java.[util]`, `import android.[view]`, `import java.[io]`,
    `import org.springframework.beans.[factory]`, Go's `"[net]/http"` (about 21 on average);
  - the root itself (`java`, `android`, `org`, ...) is moderately positive (about 11);
  - any other lowercase package name, such as the `example` in `com.example`, is near 2;
  - C header names (`<stdio.h>`, `<math.h>`) are negative (about -13);
  - a diff hunk marker (` @@`) is negative (about -20).
Everything outside import lines is predicted as 0. The main sign is that the value depends on
which library a package belongs to, not on the token alone. The program reads the text so far
to know whether the current token sits on an import line, and resets at each new line and each
new document.
"""

import re

READS = ()

# Package names of well-known standard and framework libraries (Java, Android, Go, C#).
LIBRARY_PACKAGES = set(
    """
util io nio lang net awt swing sql text math time concurrent reflect security beans
annotation view content graphics app widget os hardware media database support
springframework apache junit web servlet http context factory bukkit hibernate
stereotype event bind core data file crypto encoding path fmt log bytes strings sync
Threading Runtime Collections Linq IO Text Net
""".split()
)
# Roots of the libraries above: the first package name of a Java or Android import.
ROOTS = {"java", "javax", "android", "androidx", "org", "kotlin", "System"}
# C and C++ header names: their `#include <...>` lines are negative.
C_HEADERS = {"h", "hpp", "stdio", "stdlib", "iostream", "unistd", "stdint", "string"}
IMPORT_LINE = re.compile(r"^\s*(\d+\t)?\s*(import|using|#include|package)\b")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry["doc"] or tok.startswith("<|endoftext|>"):
        carry = {"doc": doc, "line": "", "root": None}
        if tok.startswith("<|endoftext|>"):
            return carry, 0.0
    if "\n" in tok:
        # A new line starts after the newline; the text before it no longer matters.
        carry["line"], carry["root"] = tok.rsplit("\n", 1)[-1], None
        return carry, 0.0
    line = carry["line"]
    carry["line"] = (line + tok)[:200]  # only the start of a line matters
    value = 0.0
    if IMPORT_LINE.match(line):
        seg = tok.strip().lstrip(".")
        if re.fullmatch(r"[A-Za-z]\w*", seg) and tok[:1] in '. "':
            if seg in C_HEADERS:
                value = -13.0
            elif seg in LIBRARY_PACKAGES:
                value = 21.0
            elif carry["root"] is None and seg in ROOTS:
                value = 11.0
            elif re.fullmatch(r"[a-z]\w*", seg):
                value = 2.0
            if carry["root"] is None:
                carry["root"] = seg
    elif tok.strip() == "@@":
        value = -20.0
    return carry, value

"""Rough token-class model of one down_proj component in layer 15.

This component's activation is mostly noise around zero (mean 0.03, std 0.5).
No simple rule explains much of it; the few consistent tendencies on harvested
and random text are:
  - the keyword "return" at the start of a code line is strongly negative (about -1.3);
  - the assignment sign "=" is moderately negative (about -0.2);
  - newlines and blank indentation are slightly positive (about +0.1);
  - identifier-like pieces (snake_case, dotted names, camelCase) are slightly positive (about +0.1);
  - the first token of each document is 0.
Everything else gets a small positive base value (about the mean).
"""
import re

READS = ()

RETURN_KEYWORD = re.compile(r"^\s*return\b")
IDENTIFIER = re.compile(r"[_.]|[a-z][A-Z]")


def step(carry, prefix, upstream):
    ids = prefix.document_ids
    if len(ids) < 2 or ids[-1] != ids[-2]:
        return carry, 0.0
    s = prefix.token_strings[-1]
    if RETURN_KEYWORD.match(s):
        value = -1.3
    elif "=" in s:
        value = -0.2
    elif "\n" in s or (s.strip() == "" and s != ""):
        value = 0.1
    elif IDENTIFIER.search(s):
        value = 0.1
    else:
        value = 0.02
    return carry, value

"""Layer 15, MLP down_proj, component 427.

What it does: a weak, context-driven feature. It sits near zero on most tokens and
rises on three kinds of word or token:
  * auxiliaries and modals that come after a subject ("are", "were", "have", "been",
    "will", "may", "can", "is", "was", "to", "not"), more strongly after a plural subject
    word ("products are", "kids have");
  * quantifiers and group words ("all", "both", "many", "some", "none", "one", "any",
    "people", "who", "which", "them");
  * colons and brackets that open a list, a block or a key (":", "]", "["),
    and code tokens that index or chain over a collection ("[i", "++)", ".push", ".append").
Everything else gets 0. The values are rounded least-squares fits on training rows.
The program explains only about 2% of the variance: the component's activation depends on
longer context than word classes capture, and its effect on the next-token output is tiny.
"""

READS = ()

# Auxiliaries and modals that take a subject before them.
AUX = {"are", "were", "have", "been", "being", "be", "will", "must", "may", "can", "would",
       "should", "could", "might", "has", "had", "is", "was", "not", "to"}
# Quantifiers and group words, often followed by a plural verb.
QUANT = {"all", "both", "many", "most", "some", "none", "several", "few", "those", "these",
         "people", "who", "which", "that", "one", "no", "any", "such", "more", "other",
         "everyone", "everything", "nothing", "neither", "them"}
# Colons and brackets that open a list, a block or a key.
OPENERS = {":", "]", "[", '":'}
# Code tokens that index or chain over a collection.
COLLECTION_CODE = {"[i", "[j", "[k", "++)", "++", ".push", ".append", ".filter", ".map",
                   ".forEach", ".add"}


def is_plural_word(word):
    """A rough plural noun: a longer alphabetic word ending in s (not ss)."""
    return len(word) > 3 and word.isalpha() and word.endswith("s") and not word.endswith("ss")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in COLLECTION_CODE:
        return None, 2.9
    if word in AUX:
        previous = prefix.token_strings[-2].strip() if len(prefix.token_strings) > 1 else ""
        return None, 0.6 if is_plural_word(previous) else 0.25
    if word in QUANT:
        return None, 0.45
    if word in OPENERS:
        return None, 0.6
    return None, 0.0

"""Question-word and vague-word detector, for layer 15 MLP unit 429 (component 429).

What this component is: its input direction is almost entirely one MLP hidden unit of layer
15 (about 64% of its energy sits on that unit alone), so its activation is that unit's value.
The unit is strongly negative where the text opens an embedded question ("know what it is",
"focus on how to ..."), and in vague, open-ended wording ("things", "really", "get").
Its output direction, read through the unembedding, promotes question words when negative.

What this program does, in plain terms: it predicts a negative value on
  - "what", "how", "why" that begin an embedded question mid-sentence: about -2.7;
  - other question words (who, where, which, whether, when) in that spot: about -0.7;
  - question words that open a sentence ("What is ...?"): mild;
  - the next three tokens after an embedded question word: mild;
  - vague words (things, stuff, people, ways, something): about -1.0;
  - intensifiers (really, actually, truly, simply): about -0.8;
  - get/do-type verbs (get, do, going, look, know): about -0.5;
and a positive value on feeling words that take a clause (wonder, glad, proud, sure): +0.7.
Every other position predicts 0. The numbers are group means on training rows, rounded.

What it leaves out: most of this unit's variance is diffuse and depends on context in ways
no short list captures, so this explains only a few percent of the variance.
"""

READS = ()

# Question words that open an embedded question mid-sentence, and their typical activation.
EMBEDDED_QUESTION = {"what": -2.7, "how": -2.6, "why": -2.7}
# Other question words: much weaker in the same position.
OTHER_QUESTION_WORDS = {"who", "where", "which", "whether", "when", "whatever"}
VAGUE_WORDS = {"things", "stuff", "something", "anything", "people", "ways", "way", "lot", "kinds"}
INTENSIFIERS = {"really", "actually", "truly", "simply", "basically", "exactly", "just"}
GENERIC_VERBS = {"get", "getting", "do", "doing", "going", "look", "know"}
FEELING_WORDS = {"wonder", "wondering", "glad", "proud", "excited", "grateful", "sure", "hope"}
# Tokens that end a sentence or open a quote: a question word after one of these starts a sentence.
BREAKS = {".", "?", "!", '"', "\n", "“", "”", "'", "‘", "’", "", ":"}
CLAUSE_TAIL = 3  # tokens after an embedded question word still counted as inside its clause


def step(carry, prefix, upstream):
    """carry: tokens since the last question word that opened an embedded question."""
    word = prefix.token_strings[-1].strip().lower()
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    since = 99 if new_doc or carry is None else carry
    before = "" if new_doc else prefix.token_strings[-2].strip()
    mid_sentence = before not in BREAKS

    if word in EMBEDDED_QUESTION:
        since = 0
        value = EMBEDDED_QUESTION[word] if mid_sentence else -0.4
    elif word in OTHER_QUESTION_WORDS:
        since = 0
        value = -0.7 if mid_sentence else -0.2
    else:
        since += 1
        if since <= CLAUSE_TAIL:
            value = -0.4
        elif word in VAGUE_WORDS:
            value = -1.0
        elif word in INTENSIFIERS:
            value = -0.8
        elif word in GENERIC_VERBS:
            value = -0.5
        elif word in FEELING_WORDS:
            value = 0.7
        else:
            value = 0.0
    return since, value

"""Prenominal-modifier detector for layers.15.mlp.down_proj component 442.

What the component does, in plain terms: it is high on a word that opens a noun
phrase and modifies a head noun that comes after it: "the [first] stars",
"a [full] service", "a [new] farm", "[high] school". It is about average on
nouns, and near zero or lower on determiners and prepositions.

This program predicts it from the current word and the word before it:

  - the current word's kind: a modifier (ordinal, quantity, size or age word,
    or a prefix like non-/multi-/pre-), an adjective (WordNet: adjective and not
    noun), a noun, a determiner, a preposition, or anything else;
  - whether the previous word is a determiner or possessive ("the", "its"), or a
    preposition ("of", "for"), which both tend to open a noun phrase;
  - the first token of a document, which is predicted as near zero.

Values are a linear sum of those terms, fitted by least squares on 4096 training
rows (about 2M tokens). It explains only a small share of the variance (about
4%): most of the component's variation is within a word, depending on context
this program cannot see, such as what word comes next.
"""

from collections.abc import Mapping

import wordnet

READS: tuple[str, ...] = ()

DETERMINERS = {
    "the", "a", "an", "its", "our", "their", "his", "her", "my", "your",
    "this", "that", "these", "those", "some", "each", "every", "any", "no", "all", "both",
}
PREPOSITIONS = {
    "of", "for", "with", "by", "in", "on", "to", "from", "at", "into", "about",
    "than", "over", "under", "between", "as",
}
# Words that almost always come before a noun: ordinals, quantities, size and
# age words, and noun-modifying prefixes.
MODIFIERS = {
    "first", "second", "third", "last", "next", "single", "one", "two", "three",
    "four", "five", "multiple", "several", "many", "few", "double", "high", "low",
    "large", "small", "long", "short", "full", "new", "big", "free", "best", "good",
    "main", "total", "whole", "non", "pre", "post", "multi", "sub", "self", "inter",
    "anti", "semi", "mid",
}

# Fitted weights (see the docstring): base value per kind of word, and a bonus
# from the previous word.
KIND_WEIGHT = {"modifier": 1.08, "adjective": 0.24, "noun": -0.07, "other": -0.17,
               "determiner": -0.30, "preposition": -0.39}
PREV_WEIGHT = {"determiner": 0.52, "preposition": 0.22}
INTERCEPT = 0.38


def kind_of(token: str) -> str:
    """The kind of word a token is: a modifier, adjective, noun, function word or other."""
    word = token.strip().lower()
    if not word or not word.isalpha():
        return "other"
    if word in DETERMINERS:
        return "determiner"
    if word in PREPOSITIONS:
        return "preposition"
    if word in MODIFIERS:
        return "modifier"
    senses = wordnet.parts_of_speech(word)
    if "adjective" in senses and "noun" not in senses:
        return "adjective"
    if "noun" in senses:
        return "noun"
    return "other"


def prev_kind(token: str) -> str:
    """Whether a token is a determiner, a preposition, or neither."""
    word = token.strip().lower()
    if word in DETERMINERS:
        return "determiner"
    if word in PREPOSITIONS:
        return "preposition"
    return "other"


def step(carry, prefix, upstream: Mapping):
    """The component's activation at the newest token, from the words around it."""
    ids = prefix.document_ids
    if len(ids) < 2 or ids[-1] != ids[-2]:
        return None, 0.0  # first token of a document: near zero
    value = INTERCEPT + KIND_WEIGHT[kind_of(prefix.token_strings[-1])]
    value += PREV_WEIGHT.get(prev_kind(prefix.token_strings[-2]), 0.0)
    return None, float(value)
